// test2b-rectangle: the test2b input class for rectangular C^{m x n} = A^{m x k} * B^{k x n}
// with m, n, and k pairwise distinct. The inputs are generated by
// init_test2b_rectangle_matrices (include/init_matrices.hpp), which keeps every row and
// column of A and B at roughly equal norm even when m < k or n < k.
//
// The dimension sweep is driven by LOG2_MIN_DIM..LOG2_MAX_DIM exactly as in the square
// tests, with each of m, n, k offset from the sweep exponent d:
//     m = 2^(d + LOG2_M_OFFSET),  n = 2^(d + LOG2_N_OFFSET),  k = 2^(d + LOG2_K_OFFSET)
// The three offsets must be pairwise distinct so that m != n, m != k, and n != k.
// The defaults (0, -1, +1) give n < m < k, i.e. min(m,n,k) < k, the case the
// rectangular construction is designed for. Override on the make command line, e.g.
//     make run_test2b_rectangle LOG2_M_OFFSET=1 LOG2_N_OFFSET=0 LOG2_K_OFFSET=-1
// to test k < min(m,n).
//
// The error metric is max componentwise f_A(n), computed as in test2 (test2c), against a
// high-precision reference. Results go to results/raw_data/test2b_rectangle/.

#include "dgemm_wrapper.hpp"
#include "init_matrices.hpp"
#include "utils.hpp"
#include <vector>
#include <cstdlib>
#include <cstdint>
#include <cstdio>
#include "reference_gemm.hpp"

#define RAW_DATA_DIR "results/raw_data/"

#ifndef INPUT_TYPE
#define INPUT_TYPE "test2b_rectangle"
#endif

#ifndef LOG2_M_OFFSET
#define LOG2_M_OFFSET 0
#endif
#ifndef LOG2_N_OFFSET
#define LOG2_N_OFFSET -1
#endif
#ifndef LOG2_K_OFFSET
#define LOG2_K_OFFSET 1
#endif

static_assert( LOG2_M_OFFSET != LOG2_N_OFFSET && LOG2_M_OFFSET != LOG2_K_OFFSET && LOG2_N_OFFSET != LOG2_K_OFFSET,
               "test2b-rectangle requires m, n, k pairwise distinct: LOG2_M_OFFSET, LOG2_N_OFFSET, LOG2_K_OFFSET must differ." );
static_assert( LOG2_MIN_DIM + LOG2_M_OFFSET >= 1 && LOG2_MIN_DIM + LOG2_N_OFFSET >= 1 && LOG2_MIN_DIM + LOG2_K_OFFSET >= 1,
               "test2b-rectangle: LOG2_MIN_DIM plus each offset must be >= 1 (so every dimension is >= 2)." );

// 2^(log2_base + offset)
static inline int offset_dim( const int log2_base, const int offset ){
    return 1 << (log2_base + offset);
}

int main(){

    std::string raw_data_dir = RAW_DATA_DIR;
    std::string path_string;

    char transa = 'N';
    char transb = 'N';
    double alpha = 1.0;
    double beta = 0.0;
    int seed = 0;

    // leading dimensions are fixed at the largest m / k the sweep will reach
    const int max_m = offset_dim(LOG2_MAX_DIM, LOG2_M_OFFSET);
    const int max_n = offset_dim(LOG2_MAX_DIM, LOG2_N_OFFSET);
    const int max_k = offset_dim(LOG2_MAX_DIM, LOG2_K_OFFSET);
    const int lda = max_m;
    const int ldb = max_k;
    const int ldc = max_m;

    std::vector<double> A(max_m*max_k);
    std::vector<double> B(max_k*max_n);
    std::vector<double> C(max_m*max_n);
#if REFERENCE_GEMM == 1
    std::vector<double> C_ref(max_m*max_n);
    std::vector<double> absA_absB_product(max_m*max_n);
#elif REFERENCE_GEMM == 2
    std::vector<long double> C_ref(max_m*max_n);
    std::vector<long double> absA_absB_product(max_m*max_n);
#endif

    for ( int d = LOG2_MIN_DIM; d <= LOG2_MAX_DIM; ++d ){

        const int m = offset_dim(d, LOG2_M_OFFSET);
        const int n = offset_dim(d, LOG2_N_OFFSET);
        const int k = offset_dim(d, LOG2_K_OFFSET);

        for ( int s = LOG2_MIN_SCALING_FACTOR; s <= LOG2_MAX_SCALING_FACTOR; s += LOG2_INC_SCALING_FACTOR ){

            // initialize A and B
            init_matrices(INPUT_TYPE, s, seed, m, n, k, &A[0], lda, &B[0], ldb, raw_data_dir);

            // Build inclusion mask: entry (i,j) is 0 if any summand A[i,t]*B[t,j] < 0,
            // indicating that we are not to compute f_A(n) at C[i,j].
            // (All test2b_rectangle entries are positive, so this keeps every entry; the
            // mask is retained so a sign-flipped variant can drop in without other changes.)
            std::vector<uint8_t> include_mask(m * n, 1);
            for ( int i = 0; i < m; ++i ){
                for ( int j = 0; j < n; ++j ){
                    for ( int t = 0; t < k; ++t ){
                        if ( A[i + t*lda] * B[t + j*ldb] < 0.0 ){
                            include_mask[i + j*m] = 0;
                            break;
                        }
                    }
                }
            }

            // call the DGEMM implementation under test
            init_zero_matrix(m, n, &C[0], ldc);
            dgemm_wrapper(transa, transb, m, n, k, alpha, &A[0], lda, &B[0], ldb, beta, &C[0], ldc);

            // write C to disk
            path_string = raw_data_dir + construct_metadata_path(DGEMM_IMPL_NAME, INPUT_TYPE, m, n, k, s);
            dump_matrix(m, n, &C[0], ldc, path_string + "/values.fp64");

            // either load a cached C_ref or compute from scratch and cache for later
            path_string = raw_data_dir + construct_metadata_path("C_ref", INPUT_TYPE, m, n, k, s);
            if ( ! load_matrix(path_string + "/values.fp" + std::to_string(sizeof(C_ref[0])*8), m, n, &C_ref[0], ldc ) ){
                init_zero_matrix(m, n, &C_ref[0], ldc);
                reference_gemm(&transa, &transb, &m, &n, &k, &alpha, &A[0], &lda, &B[0], &ldb, &beta, &C_ref[0], &ldc);
                dump_matrix(m, n, &C_ref[0], ldc, path_string + "/values.fp" + std::to_string(sizeof(C_ref[0])*8));
            }

            // either load a cached absA_absB_product or compute from scratch and cache for later
            path_string = raw_data_dir + construct_metadata_path("absA_absB_product", INPUT_TYPE, m, n, k, s);
            if ( ! load_matrix(path_string + "/values.fp" + std::to_string(sizeof(absA_absB_product[0])*8), m, n, &absA_absB_product[0], ldc ) ){
                abs_matrix(m, k, &A[0], lda);
                abs_matrix(k, n, &B[0], ldb);
                init_zero_matrix(m, n, &absA_absB_product[0], ldc);
                reference_gemm(&transa, &transb, &m, &n, &k, &alpha, &A[0], &lda, &B[0], &ldb, &beta, &absA_absB_product[0], &ldc);
                dump_matrix(m, n, &absA_absB_product[0], ldc, path_string + "/values.fp" + std::to_string(sizeof(absA_absB_product[0])*8));
            }

            // compute max f_A(n) and write scalar to disk
            double max_f = calculate_max_f_of_n(m, n, &C[0], ldc, &C_ref[0], ldc, &absA_absB_product[0], ldc, include_mask.data(), m);
            path_string = raw_data_dir + construct_metadata_path(DGEMM_IMPL_NAME, INPUT_TYPE, m, n, k, s);
            dump_scalar(max_f, path_string + "/max_f_of_n.fp64");

            // the plotting scripts assume m = n = k, so summarize each cell here instead
            printf("    %s  m=%d n=%d k=%d  scale=2^±%d  max f_A(n) = %.4g  (k = %d)\n",
                   INPUT_TYPE, m, n, k, s, max_f, k);
        }
    }
    return 0;
}
